const X = window.GYX;

/* ==== 🚶 陪你散步 ==== */
try { new Function('X', 'applyMacros', "/* 🚶 陪你散步：出门的时候打开它，TA 就「走在你旁边」——按你真实走过的路记下路线，每走一段、每过几分钟 TA 说一句（风大不大、累不累、看到什么了）；回来后路线画成一张小图，TA 写一句散步日记。定位不在手机上也能用，按时间陪你走 */\nif (window.__gyxWalk) return; window.__gyxWalk = 1;\nX.feat('gyxWalk', { n: '🚶 陪你散步', desc: '按真实路线陪你走，每走一段 TA 说一句，回来画路线' });\nconst S = X.store('walk');\nlet D = { walks: [], cfg: { m: 500, min: 5, voice: false } };   // [{id, cid, start, end, dist, pts:[[lat,lon,t]], talk:[{t,at}], diary}]\nlet W = null, WID = null, TM = null, busy = false;\nconst hv = (a, b) => { const R = 6371000, r = x => x * Math.PI / 180, dl = r(b[0] - a[0]), dn = r(b[1] - a[1]); const h = Math.sin(dl / 2) ** 2 + Math.cos(r(a[0])) * Math.cos(r(b[0])) * Math.sin(dn / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(h)); };\nconst km = m => m < 1000 ? Math.round(m) + ' 米' : (m / 1000).toFixed(2) + ' 公里';\nconst mins = ms => Math.max(0, Math.round(ms / 60000)) + ' 分钟';\nfunction svg(pts, w, h) {\n    if (!pts || pts.length < 2) return `<svg viewBox=\"0 0 ${w} ${h}\" width=\"100%\"><text x=\"50%\" y=\"50%\" text-anchor=\"middle\" fill=\"#aaa\" font-size=\"13\">${pts && pts.length ? '还在原地' : '没有定位，只按时间陪你走'}</text></svg>`;\n    const la = pts.map(p => p[0]), lo = pts.map(p => p[1]), a = Math.min(...la), b = Math.max(...la), c = Math.min(...lo), d = Math.max(...lo), s = Math.max(b - a, (d - c) * Math.cos(a * Math.PI / 180), 1e-5);\n    const P = pts.map(p => [10 + (p[1] - c) * Math.cos(a * Math.PI / 180) / s * (w - 20), h - 10 - (p[0] - a) / s * (h - 20)]);\n    return `<svg viewBox=\"0 0 ${w} ${h}\" width=\"100%\"><polyline points=\"${P.map(p => p.map(v => v.toFixed(1)).join(',')).join(' ')}\" fill=\"none\" stroke=\"#5ac8a8\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><circle cx=\"${P[0][0]}\" cy=\"${P[0][1]}\" r=\"5\" fill=\"#34c759\"/><circle cx=\"${P[P.length - 1][0]}\" cy=\"${P[P.length - 1][1]}\" r=\"6\" fill=\"#ff6b8b\"/></svg>`;\n}\nasync function talk(why) {\n    if (!W || busy) return; busy = true; const c = X.char(W.cid), el = Date.now() - W.start;\n    let t = null;\n    try { const wx = typeof window.gymapWeatherInfo === 'function' ? await window.gymapWeatherInfo() : null; const h = new Date().getHours();\n        t = X.bailu() ? null : await X.ask(`${X.who(c)}\\n你正「走在她旁边」陪她散步（她开着定位，你看得到她走了多远）。已经走了 ${km(W.dist)}、${mins(el)}，现在 ${h} 点${wx ? '，天气：' + [wx.city, wx.desc, wx.now != null ? wx.now + '°' : ''].filter(Boolean).join(' ') : ''}。${why}\\n刚才你说过：${W.talk.slice(-3).map(x => x.t).join(' / ') || '（还没说话）'}\\n像真的走在她身边一样说一句（短，口语，别重复刚才的话）。`); } catch (e) {}\n    if (!t) t = X.pick(X.cards(['散步', '陪伴'], c, 3).concat([`走了${km(W.dist)}了，累不累？`, '风有点大，你衣服穿够没？', '慢点走，我跟得上。', '你看左边——算了，我也看不见，你给我讲讲。', '要是我真的在就好了，可以牵着你的手。', `已经${mins(el)}了，要不要找个地方坐会儿？`, '前面有没有好看的花？拍给我看看。']));\n    W.talk.push({ t: X.plain(t), at: Date.now() }); busy = false; paint(); if (D.cfg.voice) X.speak(c, t);\n}\nfunction onPos(p) { if (!W) return; const q = [p.coords.latitude, p.coords.longitude, Date.now()]; const last = W.pts[W.pts.length - 1]; if (p.coords.accuracy > 80 && W.pts.length) return; if (last) { const d = hv(last, q); if (d < 6) return; W.dist += d; } W.pts.push(q); if (W.dist - W.lastM >= (+D.cfg.m || 500)) { W.lastM = W.dist; talk(`你们刚又走了 ${km(+D.cfg.m || 500)}。`); } paint(); }\nwindow.gyxWalkStart = cid => {\n    const c = X.char(cid) || X.cur(); if (!c || W) return; W = { id: 'wk' + Date.now().toString(36), cid: String(c.id), start: Date.now(), dist: 0, lastM: 0, lastT: Date.now(), pts: [], talk: [] };\n    try { if (navigator.geolocation) WID = navigator.geolocation.watchPosition(onPos, e => { W && (W.geoErr = e.message || '定位不可用'); paint(); }, { enableHighAccuracy: true, maximumAge: 5000, timeout: 20000 }); else W.geoErr = '这台设备没有定位'; } catch (e) { W.geoErr = '定位不可用'; }\n    TM = setInterval(() => { if (W && Date.now() - W.lastT >= (+D.cfg.min || 5) * 60000) { W.lastT = Date.now(); talk(''); } paint(); }, 15000);\n    talk('你们刚出门。'); window.gyxWalkOpen(c.id);\n};\nwindow.gyxWalkStop = async () => {\n    if (!W) return; try { if (WID != null) navigator.geolocation.clearWatch(WID); } catch (e) {} clearInterval(TM); WID = null; const w = W; W = null; w.end = Date.now(); const c = X.char(w.cid);\n    let d = X.bailu() ? null : await X.ask(`${X.who(c)}\\n你刚陪她散完步：${km(w.dist)}、${mins(w.end - w.start)}。路上你说过：${w.talk.map(x => x.t).join(' / ')}\\n写一句散步日记（30 字以内）。`);\n    w.diary = X.plain(d || X.v(`今天陪你走了${km(w.dist)}。下次换我走在外侧。`, `${mins(w.end - w.start)}，${km(w.dist)}。你走路的样子我想象得到。`, '散步回来了。希望你今天心情好一点点。'));\n    delete w.lastM; delete w.lastT; D.walks.unshift(w); await S.set('d', D);\n    X.say(c, `🚶 ${w.diary}`); window.gyxWalkOpen(w.cid);\n};\nfunction paint() { const b = document.getElementById('gyxWkLive'); if (!b || !W) return; b.innerHTML = `<div class=\"wk-num\"><b>${km(W.dist)}</b><span>${mins(Date.now() - W.start)}</span></div>${svg(W.pts, 320, 160)}${W.geoErr ? `<div class=\"gyx-tip\">📍 ${X.esc(W.geoErr)}——只按时间陪你走</div>` : ''}<div class=\"wk-talk\">${W.talk.slice(-5).reverse().map(x => `<div>💬 ${X.esc(x.t)}</div>`).join('')}</div>`; }\nwindow.gyxWalkCfg = (k, v) => { D.cfg[k] = v; S.set('d', D); };\nwindow.gyxWalkDel = async id => { D.walks = D.walks.filter(x => x.id !== id); await S.set('d', D); window.gyxWalkOpen(); };\nwindow.gyxWalkOpen = function (who) {\n    const c = (W && X.char(W.cid)) || X.char(who) || X.cur(); if (!c) return; const cid = String(c.id);\n    X.panel('gyxWalkOv', '🚶 和 ' + X.esc(X.name(c)) + ' 散步', W ? `<div id=\"gyxWkLive\"></div><div class=\"gyx-row\" style=\"justify-content:center\"><button class=\"gyx-btn\" onclick=\"gyxWalkStop()\">到家了</button><button class=\"gyx-btn lite\" onclick=\"this.disabled=true;setTimeout(()=>this.disabled=false,4000);gyxWalkTalk()\">跟 TA 说说话</button></div>`\n        : `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxWalkOpen')}<button class=\"gyx-btn\" onclick=\"gyxWalkStart('${cid}')\">出门啦</button></div><div class=\"gyx-tip\">${X.v('开着这个页面走，TA 就在你旁边。', '出门记得带上 TA。', '你走多远，TA 陪多远。')}手机锁屏后定位可能会停，回来点「到家了」就行。</div>\n        <div class=\"gyx-row gyx-tip\">每走 <input class=\"gyx-who\" type=\"number\" min=\"100\" step=\"100\" value=\"${D.cfg.m}\" style=\"width:70px\" onchange=\"gyxWalkCfg('m',+this.value)\"> 米 / 每 <input class=\"gyx-who\" type=\"number\" min=\"1\" value=\"${D.cfg.min}\" style=\"width:50px\" onchange=\"gyxWalkCfg('min',+this.value)\"> 分钟 TA 说一句 · <label><input type=\"checkbox\" ${D.cfg.voice ? 'checked' : ''} onchange=\"gyxWalkCfg('voice',this.checked)\"> 念出来（戴耳机）</label></div>\n        ${D.walks.filter(x => x.cid === cid).slice(0, 20).map(x => `<div class=\"gyx-card\"><div class=\"wk-num\"><b>${km(x.dist)}</b><span>${new Date(x.start).toLocaleString()} · ${mins(x.end - x.start)}</span><i onclick=\"gyxWalkDel('${x.id}')\">删</i></div>${svg(x.pts, 320, 110)}<div class=\"gyx-tip\">${X.esc(x.diary || '')}</div></div>`).join('') || '<div class=\"gyx-tip\">还没一起散过步</div>'}`);\n    paint();\n};\nwindow.gyxWalkData = () => D;\nwindow.gyxWalkTalk = () => talk('她想跟你说说话。');\nX.ctx(id => { if (W && W.cid === String(id)) return `【你正在陪她散步】已经 ${km(W.dist)}、${mins(Date.now() - W.start)}，你「走在她旁边」。`; const x = D.walks.find(w => w.cid === String(id)); return x && Date.now() - x.end < 6 * 36e5 ? `【刚才陪她散了步】${km(x.dist)}，${mins(x.end - x.start)}。` : ''; }, 'gyxWalk');\nX.action({ key: 'gyx_walk', label: '约她出去走走，你陪着', hint: '陪你散步', need: c => { const h = new Date().getHours(); return h >= 7 && h <= 21 && !D.walks.some(x => x.cid === String(c.id) && Date.now() - x.end < 2 * 864e5); },\n    run: async c => (await X.reach(c, '你想让她出去走走透透气，你会「陪着她」（她可以开「🚶 陪你散步」）。用你的方式约她')) ? '约你出去走走' : null }, 'gyxWalk');\nX.today(() => ({ title: '🚶 散步', rows: (W ? [{ t: '进行中', x: km(W.dist) + ' · ' + mins(Date.now() - W.start), go: 'gyxWalkOpen()' }] : []).concat(D.walks.filter(x => X.day(new Date(x.start)) === X.day()).map(x => ({ t: km(x.dist), x: '和 ' + X.esc(X.name(X.char(x.cid))) + ' 散了步', go: `gyxWalkOpen('${x.cid}')` }))) }), 'gyxWalk');\nX.widget('gyxWalkW', { n: '陪你散步', sizes: ['s', 'm'], tap: () => window.gyxWalkOpen(), r: w => { if (W) return X.gw(w, '🚶', '散步中', [km(W.dist), mins(Date.now() - W.start)]); const tot = D.walks.reduce((a, x) => a + x.dist, 0); return X.gw(w, '🚶', '陪你散步', D.walks.length ? ['一共 ' + km(tot), D.walks.length + ' 次'] : ['出去走走？']); } }, 'gyxWalk');\nX.memArr({ k: 'gyxWalk', ico: '🚶', n: '散步', d: '一起散过的步和散步日记', arr: () => D.walks, field: 'diary', text: x => x.diary || '', meta: x => new Date(x.start).toLocaleString() + ' · ' + km(x.dist), save: () => S.set('d', D) }, 'gyxWalk');\nX.css('gyxWalkCss', `.wk-num{display:flex;align-items:baseline;gap:10px;margin:6px 0}.wk-num b{font-size:26px}.wk-num span{color:#888;font-size:12.5px;flex:1}.wk-num i{font-style:normal;font-size:11px;color:#aaa;cursor:pointer}.wk-talk div{padding:6px 0;font-size:14px;border-bottom:1px dashed #eee}#gyxWkLive svg{background:#f4fbf8;border-radius:14px}`);\nX.mini({ id: 'gyxWalk', icon: '🚶', title: '陪你散步', desc: '按真实路线陪你走，每走一段说一句', cat: '陪伴', onOpen: () => window.gyxWalkOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.walks = D.walks || []; D.cfg = Object.assign({ m: 500, min: 5, voice: false }, D.cfg || {}); })();\n\n//# sourceURL=gyx-plugin/陪你散步.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🚶 陪你散步 出错：', e); }
/* ==== 🍳 一起做饭 ==== */
try { new Function('X', 'applyMacros', "/* 🍳 一起做饭：选一道菜，TA 一步一步教你做——每一步有计时器，TA 在旁边说话（能用 TA 的声音念）；做完拍张照给 TA 看，你们做过的菜都记着 */\nif (window.__gyxCook) return; window.__gyxCook = 1;\nX.feat('gyxCook', { n: '🍳 一起做饭', desc: 'TA 一步一步教你做菜，陪你做完' });\nconst S = X.store('cook');\nlet D = { log: [], cfg: { voice: true } };\nlet K = null;   // 正在做：{cid, dish, steps:[{s, min, say}], i, t0, timer, left}\nconst IDEAS = ['番茄炒蛋', '可乐鸡翅', '蛋炒饭', '红烧肉', '清炒时蔬', '酸辣土豆丝', '葱油拌面', '番茄牛腩', '麻婆豆腐', '蒸蛋羹', '咖喱饭', '寿喜锅', '三明治', '松饼', '热红酒', '红糖姜茶', '皮蛋瘦肉粥', '宫保鸡丁', '糖醋排骨', '冬阴功汤'];\nconst LOCAL = { '番茄炒蛋': [['番茄切块，鸡蛋打散加一点点盐', 0, '刀小心点，我看着呢'], ['热锅倒油，油热了倒蛋液，凝固就盛出来', 2, '蛋别炒太老，嫩一点好吃'], ['再加点油，下番茄炒出汁', 3, '可以压一压，汁多一点'], ['倒回鸡蛋，加盐和一点点糖，翻匀', 1, '好香，我都闻到了'], ['出锅！', 0, '第一口给我尝尝']], '蛋炒饭': [['隔夜饭打散，鸡蛋打匀', 0, '隔夜饭最好吃'], ['油热下蛋液，快速划散', 1, '手快一点'], ['下米饭大火翻炒', 3, '炒到米粒跳起来'], ['加盐、葱花，翻匀出锅', 1, '真厉害']], '红糖姜茶': [['姜切片', 0, '多切几片，暖一点'], ['水里放姜煮开', 5, '等水开的时候陪我说说话'], ['加红糖再煮一会儿', 3, '小心烫'], ['倒出来，慢慢喝', 0, '喝完肚子就暖了']] };\nasync function recipe(c, dish) {\n    if (X.bailu() || !X.who) { const r = LOCAL[dish] || LOCAL['番茄炒蛋']; return r.map(([s, min, say]) => ({ s, min, say: X.cards(['做饭', '聊天'], c, 1)[0] || say })); }\n    const j = X.json(await X.ask(`${X.who(c)}\\n她想和你一起做「${dish}」，你来一步一步教她。步骤要真实可做（家常做法），每步写清楚做什么、大概要几分钟（不需要等就写 0），再加一句你在旁边会说的话（按你的性格：心疼、调侃、夸她、偷吃……）。4~9 步。\\n只输出 JSON：{\"steps\":[{\"s\":\"这一步做什么\",\"min\":分钟数,\"say\":\"你说的话\"}]}`));\n    if (j && Array.isArray(j.steps) && j.steps.length) return j.steps.map(x => ({ s: String(x.s || ''), min: Math.max(0, +x.min || 0), say: String(x.say || '') }));\n    const r = LOCAL[dish] || LOCAL['番茄炒蛋']; return r.map(([s, min, say]) => ({ s, min, say }));\n}\nwindow.gyxCookStart = async function (dish, who) {\n    const c = X.char(who) || X.cur(); if (!c) return; dish = String(dish || '').trim() || X.pick(IDEAS);\n    const b = document.getElementById('gyxCkBody'); if (b) b.innerHTML = `<div class=\"ck-wait\">${X.esc(X.name(c))} 在想「${X.esc(dish)}」怎么做……</div>`;\n    const steps = await recipe(c, dish);\n    K = { cid: String(c.id), dish, steps, i: 0, t0: Date.now(), left: 0 };\n    paint(); say(); return K;\n};\nfunction say() { if (!K) return; const st = K.steps[K.i], c = X.char(K.cid); if (st && st.say && D.cfg.voice) X.speak(c, st.say); }\nwindow.gyxCookNext = function (d) {\n    if (!K) return; clearInterval(K.timer); K.left = 0; K.i = Math.max(0, K.i + (d || 1));\n    if (K.i >= K.steps.length) return done(); paint(); say();\n};\nwindow.gyxCookTimer = function () {\n    if (!K) return; const st = K.steps[K.i]; clearInterval(K.timer); K.left = Math.round((st.min || 1) * 60);\n    K.timer = setInterval(() => { if (!K) return; K.left--; const e = document.getElementById('gyxCkT'); if (e) e.textContent = mmss(K.left); if (K.left <= 0) { clearInterval(K.timer); ding(); X.toast(X.v('⏰ 时间到了', '⏰ 好了，下一步', '⏰ 叮！'), K.steps[K.i].s); const c = X.char(K.cid); if (D.cfg.voice) X.speak(c, X.pick(['好了，可以下一步了', '时间到啦', '叮，好了'])); } }, 1000); paint();\n};\nconst mmss = s => String(Math.floor(Math.max(0, s) / 60)).padStart(2, '0') + ':' + String(Math.max(0, s) % 60).padStart(2, '0');\nfunction ding() { try { const a = new (window.AudioContext || window.webkitAudioContext)(); [0, .18].forEach(t => { const o = a.createOscillator(), g = a.createGain(); o.frequency.value = 1320; o.connect(g); g.connect(a.destination); g.gain.setValueAtTime(.001, a.currentTime + t); g.gain.exponentialRampToValueAtTime(.2, a.currentTime + t + .02); g.gain.exponentialRampToValueAtTime(.001, a.currentTime + t + .4); o.start(a.currentTime + t); o.stop(a.currentTime + t + .45); }); } catch (e) {} }\nasync function done(photo) {\n    if (!K) return; const k = K; K = null; clearInterval(k.timer);\n    const it = { cid: k.cid, dish: k.dish, at: Date.now(), min: Math.round((Date.now() - k.t0) / 60000), photo: '' };\n    D.log.unshift(it); await S.set('d', D);\n    const b = document.getElementById('gyxCkBody');\n    if (b) b.innerHTML = `<div class=\"ck-done\"><b>🎉 「${X.esc(it.dish)}」做好啦</b><span>用了 ${it.min} 分钟</span><label class=\"gyx-btn\">📷 拍张照给 TA 看<input type=\"file\" accept=\"image/*\" style=\"display:none\" onchange=\"gyxCookPhoto(this)\"></label><button class=\"gyx-btn lite\" onclick=\"gyxCookOpen()\">回去</button></div>`;\n    const c = X.char(it.cid); X.reach(c, `你刚陪她一起做完了「${it.dish}」，说说（想尝一口、夸她、或者调侃她手忙脚乱）`);\n}\nwindow.gyxCookDone = () => done();\nwindow.gyxCookPhoto = function (inp) {\n    const f = inp.files && inp.files[0]; if (!f) return; const r = new FileReader();\n    r.onload = async () => { const it = D.log[0]; if (!it) return; it.photo = r.result; await S.set('d', D); const c = X.char(it.cid); const sid = String(c.id); if (!globalChats[sid]) globalChats[sid] = []; globalChats[sid].push({ sender: 'me', text: `[照片] 我做的「${it.dish}」`, mediaUrl: r.result, timestamp: Date.now(), readBy: [] }); try { saveAllData(); } catch (e) {} try { if (typeof triggerAIBatchReply === 'function') triggerAIBatchReply(sid, `[照片] 我做的「${it.dish}」`); } catch (e) {} X.toast(X.v('发给 TA 看了', 'TA 看到了'), it.dish); window.gyxCookOpen(); };\n    r.readAsDataURL(f);\n};\nfunction paint() {\n    const b = document.getElementById('gyxCkBody'); if (!b || !K) return;\n    const st = K.steps[K.i], c = X.char(K.cid);\n    b.innerHTML = `<div class=\"ck-top\"><b>${X.esc(K.dish)}</b><span>第 ${K.i + 1} / ${K.steps.length} 步</span></div>\n        <div class=\"ck-bar\"><i style=\"width:${(K.i + 1) / K.steps.length * 100}%\"></i></div>\n        <div class=\"ck-step\">${X.esc(st.s)}</div>\n        ${st.say ? `<div class=\"ck-say\">💬 ${X.esc(X.name(c))}：${X.esc(st.say)}</div>` : ''}\n        ${st.min ? `<div class=\"ck-tm\"><b id=\"gyxCkT\">${K.left ? mmss(K.left) : mmss(st.min * 60)}</b><button class=\"gyx-btn lite\" onclick=\"gyxCookTimer()\">${K.left ? '重新计时' : '⏱ 开始计时 ' + st.min + ' 分钟'}</button></div>` : ''}\n        <div class=\"gyx-row\" style=\"justify-content:space-between\"><button class=\"gyx-btn lite\" ${K.i ? '' : 'disabled'} onclick=\"gyxCookNext(-1)\">上一步</button><button class=\"gyx-btn\" onclick=\"gyxCookNext(1)\">${K.i === K.steps.length - 1 ? '做好了！' : '下一步'}</button></div>`;\n}\nwindow.gyxCookOpen = function (who) {\n    X.panel('gyxCkOv', '🍳 一起做饭', '<div id=\"gyxCkBody\"></div>');\n    if (K) return paint();\n    const c = X.char(who) || X.cur(), b = document.getElementById('gyxCkBody');\n    b.innerHTML = `<div class=\"gyx-row\">和谁：${X.whoSel((c || {}).id, 'gyxCookWho')}<label><input type=\"checkbox\" ${D.cfg.voice ? 'checked' : ''} onchange=\"gyxCookCfg(this.checked)\"> TA 出声说话</label></div>\n        <div class=\"gyx-row\"><input id=\"gyxCkDish\" class=\"gyx-in\" placeholder=\"想做什么菜？（空着＝TA 随便挑一道）\" style=\"flex:1\"><button class=\"gyx-btn\" onclick=\"gyxCookStart(document.getElementById('gyxCkDish').value, GYX_CK_WHO)\">开始</button></div>\n        <div class=\"gyx-row\">${X.pick([IDEAS.slice(0, 10), IDEAS.slice(10)]).map(d => `<span class=\"gyx-chip\" onclick=\"gyxCookStart('${d}', GYX_CK_WHO)\">${d}</span>`).join('')}</div>\n        ${D.log.length ? '<div class=\"gyx-tip\">我们做过的菜</div>' + D.log.slice(0, 20).map(x => `<div class=\"ck-log\">${x.photo ? `<img src=\"${x.photo}\">` : '🍽️'} <b>${X.esc(x.dish)}</b><span>${new Date(x.at).toLocaleDateString()} · 和 ${X.esc(X.name(X.char(x.cid)))}</span></div>`).join('') : ''}`;\n    window.GYX_CK_WHO = String((c || {}).id || '');\n};\nwindow.GYX_CK_WHO = '';\nwindow.gyxCookWho = v => { window.GYX_CK_WHO = v; };\nwindow.gyxCookCfg = v => { D.cfg.voice = v; S.set('d', D); };\nwindow.gyxCookState = () => K;\nwindow.gyxCookData = () => D;\nX.action({ key: 'gyx_cook', label: '约她一起做顿饭（你教她做一道菜）', hint: '饭点前后', need: () => { const h = new Date().getHours(); return (h >= 10 && h <= 13) || (h >= 16 && h <= 20); }, run: async c => (await X.reach(c, `快到饭点了，你想约她一起做「${X.pick(IDEAS)}」（你教她，在「小功能 → 一起做饭」里），用你的方式约她`)) ? '约你一起做饭' : null }, 'gyxCook');\nX.ctx(id => K && K.cid === String(id) ? `【一起做饭】你们正在一起做「${K.dish}」，现在是第 ${K.i + 1} 步：${K.steps[K.i].s}` : '', 'gyxCook');\nX.today(() => { const rows = []; if (K) rows.push({ t: '正在做', x: `${X.esc(K.dish)}（第 ${K.i + 1}/${K.steps.length} 步）`, go: 'gyxCookOpen()' }); D.log.filter(x => X.day(new Date(x.at)) === X.day()).forEach(x => rows.push({ t: '做好了', x: X.esc(x.dish), go: 'gyxCookOpen()' })); return { title: '🍳 一起做饭', rows }; }, 'gyxCook');\nX.css('gyxCkCss', `.ck-wait{padding:40px 0;text-align:center;color:#8e8e93}.ck-top{display:flex;justify-content:space-between;align-items:baseline}.ck-top b{font-size:20px}.ck-top span{font-size:13px;color:#8e8e93}.ck-bar{height:6px;border-radius:3px;background:#f0f0f3;margin:10px 0}.ck-bar i{display:block;height:100%;border-radius:3px;background:linear-gradient(90deg,#ffb86b,#ff7a59);transition:width .4s}\n.ck-step{font-size:22px;line-height:1.6;padding:18px 16px;border-radius:18px;background:#fff7ec;margin:10px 0;min-height:90px}.ck-say{font-size:14px;color:#8e4ec6;margin:6px 2px}.ck-tm{display:flex;align-items:center;gap:14px;margin:12px 0}.ck-tm b{font-size:40px;font-weight:300;font-variant-numeric:tabular-nums}\n.ck-done{display:flex;flex-direction:column;align-items:center;gap:12px;padding:30px 0}.ck-done b{font-size:22px}.ck-done span{color:#8e8e93}.ck-log{display:flex;align-items:center;gap:8px;padding:6px 0;font-size:14px}.ck-log img{width:40px;height:40px;object-fit:cover;border-radius:8px}.ck-log span{font-size:12px;color:#aaa;margin-left:auto}`);\nX.mini({ id: 'gyxCook', icon: '🍳', title: '一起做饭', desc: 'TA 一步一步教你做菜：计时器、TA 在旁边说话、做完拍照给 TA 看', onOpen: () => window.gyxCookOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.log = D.log || []; D.cfg = Object.assign({ voice: true }, D.cfg || {}); })();\nX.widget('gyxCookW', { n: '一起做饭', sizes: ['s', 'm'], tap: () => window.gyxCookOpen(), r: w => { const l = D.log[0]; return X.gw(w, '🍳', '一起做饭', K ? [X.esc(K.dish), '第 ' + (K.i + 1) + '/' + K.steps.length + ' 步'] : [l ? '上次：' + X.esc(l.dish) : '今天做点什么', D.log.length ? '一起做过 ' + D.log.length + ' 道' : '']); } }, 'gyxCook');\nX.mem