/* ==== 📚 一起自习室 ==== */
try { new Function('X', 'applyMacros', "/* 📚 一起自习室：番茄钟，TA 在对面「也在忙」；开始/休息/结束 TA 都会说话，偷偷切走太久会被念 */\nif (window.__gyxStudy) return; window.__gyxStudy = 1;\nX.feat('gyxStudy', { n: '📚 一起自习室', desc: '番茄钟，TA 在对面也在忙；休息时催你喝水，偷偷切走会被念' });\nconst S = X.store('study');\nlet D = { focus: 25, rest: 5, rounds: 4, who: '', log: [] };\nlet T = null;   // { c, phase:'focus'|'rest', end, round, task, away, awayAt, nagged }\nconst DOING = ['看书', '写东西', '回邮件', '改稿子', '画画', '背单词', '整理资料', '写代码', '看文献', '做表'];\nasync function line(c, what, extra) {\n    if (X.bailu()) return X.cards(['自习', '聊天'], c, 1)[0] || { start: '开始吧，我陪你。', rest: '休息一下，喝口水。', back: '回来了？继续。', done: '辛苦了，今天很棒。', away: '人呢？说好一起学的。' }[what];\n    const hint = { start: `你们一起开始专注 ${D.focus} 分钟${T && T.task ? '，她要做的是：' + T.task : ''}。你也在对面忙你的事（${T && T.doing}）。说一句开始前的话。`, rest: '专注时间到了，该休息了。说一句让她休息（催她喝水、活动一下、看看远处）。', back: '休息结束了，叫她回来继续。', done: `今天一共专注了 ${extra || 0} 轮，结束了。夸夸她，说说你刚才在做什么。`, away: '说好一起专注，她偷偷切走去干别的了好一会儿。按你的性格念她一句（别太凶）。' }[what];\n    const t = await X.ask(`${X.who(c)}\\n${hint}\\n只输出一句话（口语，不超过 40 字，不要动作描写）。`);\n    return t ? X.plain(t) : null;\n}\nfunction msg(c, t) { if (!t) return; X.say(c, t); try { if (window.gyxPetSay) window.gyxPetSay(t); } catch (e) {} }\nwindow.gyxStudyStart = async function () {\n    const c = X.char(D.who) || X.cur(); if (!c) { X.toast('先有一个角色'); return; }\n    const task = (document.getElementById('gyxStTask') || {}).value || '';\n    T = { c, phase: 'focus', end: Date.now() + D.focus * 60000, round: 1, task, doing: X.pick(DOING), away: 0, nagged: 0, t0: Date.now() };\n    paint(); mini(true);\n    msg(c, await line(c, 'start'));\n};\nwindow.gyxStudyStop = async function (quiet) {\n    if (!T) return; const r = T; T = null; mini(false); paint();\n    const done = r.phase === 'rest' ? r.round : r.round - 1 + (r.end - Date.now() <= 0 ? 1 : 0);\n    D.log.unshift({ at: r.t0, min: Math.round((Date.now() - r.t0) / 60000), rounds: done, task: r.task, cid: String(r.c.id) }); await S.set('d', D);\n    if (!quiet) msg(r.c, await line(r.c, 'done', done));\n};\nlet busy = false;\nasync function tick() { if (!X.on('gyxStudy')) return;\n    if (!T || busy) return; busy = true;\n    try { await tick0(); } finally { busy = false; }\n}\nasync function tick0() {\n    const left = T.end - Date.now();\n    if (left <= 0) {\n        if (T.phase === 'focus') { if (T.round >= D.rounds && D.rounds > 0) { await window.gyxStudyStop(); return; } T.phase = 'rest'; T.end = Date.now() + D.rest * 60000; ring(); msg(T.c, await line(T.c, 'rest')); }\n        else { T.phase = 'focus'; T.round++; T.end = Date.now() + D.focus * 60000; T.doing = X.pick(DOING); ring(); msg(T.c, await line(T.c, 'back')); }\n    }\n    // 专注时切走：超过 90 秒被念（每轮最多两次）\n    if (T && T.phase === 'focus' && document.hidden) { if (!T.awayAt) T.awayAt = Date.now(); else if (Date.now() - T.awayAt > 90000 && T.nagged < 2) { T.nagged++; T.awayAt = Date.now(); const t = await line(T.c, 'away'); msg(T.c, t); X.notify(T.c, `📚 ${X.name(T.c)}：${t || '人呢？'}`, '回去自习'); } }\n    else if (T) T.awayAt = 0;\n    paintTimer();\n}\nfunction ring() { try { const a = new (window.AudioContext || window.webkitAudioContext)(); const o = a.createOscillator(), g = a.createGain(); o.frequency.value = 880; o.connect(g); g.connect(a.destination); g.gain.setValueAtTime(.001, a.currentTime); g.gain.exponentialRampToValueAtTime(.2, a.currentTime + .05); g.gain.exponentialRampToValueAtTime(.001, a.currentTime + 1.2); o.start(); o.stop(a.currentTime + 1.3); } catch (e) {} }\nconst mmss = ms => { ms = Math.max(0, ms); const s = Math.round(ms / 1000); return String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0'); };\nfunction paintTimer() {\n    const t = document.getElementById('gyxStT'), m = document.getElementById('gyxStMini');\n    if (T) {\n        const left = T.end - Date.now(), tot = (T.phase === 'focus' ? D.focus : D.rest) * 60000, p = 1 - left / tot;\n        if (t) { t.textContent = mmss(left); const r = document.getElementById('gyxStRing'); if (r) r.style.strokeDashoffset = String(565 * (1 - Math.min(1, p))); }\n        if (m) m.querySelector('b').textContent = (T.phase === 'focus' ? '📚 ' : '☕ ') + mmss(left);\n    }\n}\nfunction mini(on) {\n    let m = document.getElementById('gyxStMini');\n    if (!on) { if (m) m.remove(); return; }\n    if (!m) { m = document.createElement('div'); m.id = 'gyxStMini'; m.onclick = () => window.gyxStudyOpen(); m.innerHTML = '<b></b>'; document.body.appendChild(m); }\n    paintTimer();\n}\nfunction paint() {\n    const b = document.getElementById('gyxStBody'); if (!b) return;\n    const c = T ? T.c : (X.char(D.who) || X.cur());\n    const today = D.log.filter(l => X.day(new Date(l.at)) === X.day());\n    const week = D.log.filter(l => Date.now() - l.at < 7 * 86400000).reduce((a, l) => a + l.min, 0);\n    b.innerHTML = T ? `\n        <div class=\"st-desk\"><div class=\"st-me\">你<br><small>${X.esc(T.task || '专注中')}</small></div>\n        <div class=\"st-clock\"><svg viewBox=\"0 0 200 200\"><circle cx=\"100\" cy=\"100\" r=\"90\" class=\"bg\"/><circle id=\"gyxStRing\" cx=\"100\" cy=\"100\" r=\"90\" class=\"fg ${T.phase}\" style=\"stroke-dasharray:565;stroke-dashoffset:565\"/></svg><div><b id=\"gyxStT\">--:--</b><em>${T.phase === 'focus' ? `第 ${T.round}${D.rounds ? ' / ' + D.rounds : ''} 轮 · 专注` : '休息一下'}</em></div></div>\n        <div class=\"st-ta\">${X.esc(X.name(c))}<br><small>在${X.esc(T.doing)}</small></div></div>\n        <div class=\"gyx-row\" style=\"justify-content:center\"><button class=\"gyx-btn lite\" onclick=\"gyxStudyStop()\">结束</button></div>\n        <div class=\"gyx-tip\" style=\"text-align:center\">专注时偷偷切走太久，TA 会来念你的。</div>` : `\n        <div class=\"gyx-row\">和谁：${X.whoSel(D.who || (c || {}).id, 'gyxStudyWho')}</div>\n        <input id=\"gyxStTask\" class=\"gyx-in\" placeholder=\"这次要做什么（可空）\">\n        <div class=\"gyx-row\">专注 <input class=\"gyx-who\" type=\"number\" min=\"1\" value=\"${D.focus}\" style=\"width:70px\" onchange=\"gyxStudySet('focus',this.value)\"> 分钟 · 休息 <input class=\"gyx-who\" type=\"number\" min=\"1\" value=\"${D.rest}\" style=\"width:70px\" onchange=\"gyxStudySet('rest',this.value)\"> 分钟 · <input class=\"gyx-who\" type=\"number\" min=\"0\" value=\"${D.rounds}\" style=\"width:70px\" onchange=\"gyxStudySet('rounds',this.value)\"> 轮（0＝一直循环）</div>\n        <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxStudyStart()\">开始自习</button></div>\n        <div class=\"gyx-card\">今天：${today.reduce((a, l) => a + l.rounds, 0)} 轮 · ${today.reduce((a, l) => a + l.min, 0)} 分钟　这周：${week} 分钟</div>\n        ${D.log.slice(0, 8).map(l => `<div class=\"gyx-tip\">${new Date(l.at).toLocaleString()} · ${l.min} 分钟 · ${l.rounds} 轮 ${l.task ? '· ' + X.esc(l.task) : ''} · 和 ${X.esc(X.name(X.char(l.cid)))}</div>`).join('')}`;\n    paintTimer();\n}\nwindow.gyxStudyWho = v => { D.who = v; S.set('d', D); };\nwindow.gyxStudySet = (k, v) => { D[k] = Math.max(0, +v || 0) || (k === 'rounds' ? 0 : 1); S.set('d', D); };\nwindow.gyxStudyOpen = function () { X.panel('gyxStOv', '📚 一起自习室', '<div id=\"gyxStBody\"></div>'); paint(); };\nwindow.gyxStudyState = () => T;\nX.action({ key: 'gyx_study', label: '约她一起自习 / 一起专注一会儿', hint: '你也有事要忙的时候', need: () => !T, run: async c => (await X.reach(c, '你想约她一起自习一会儿（「小功能 → 一起自习室」），你也有自己的事要忙')) ? '约你一起自习' : null }, 'gyxStudy');\nX.css('gyxStCss', `\n.st-desk{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:12px 0}.st-me,.st-ta{flex:1;text-align:center;font-size:14px}.st-me small,.st-ta small{color:#8e8e93}\n.st-clock{position:relative;width:190px;height:190px;flex-shrink:0}.st-clock svg{width:100%;height:100%;transform:rotate(-90deg)}.st-clock circle{fill:none;stroke-width:10;stroke-linecap:round}.st-clock .bg{stroke:#f0f0f3}.st-clock .fg{stroke:#ff8a65;transition:stroke-dashoffset 1s linear}.st-clock .fg.rest{stroke:#81c784}\n.st-clock>div{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center}.st-clock b{font-size:38px;font-weight:600;font-variant-numeric:tabular-nums}.st-clock em{font-style:normal;font-size:12px;color:#8e8e93}\n#gyxStMini{position:fixed;left:50%;top:10px;transform:translateX(-50%);z-index:9400;padding:6px 14px;border-radius:999px;background:rgba(20,20,22,.86);color:#fff;font-size:13px;cursor:pointer;backdrop-filter:blur(10px);font-variant-numeric:tabular-nums}\n`);\nX.today(() => { const L = D.log.filter(l => X.day(new Date(l.at)) === X.day()); const rows = []; if (T) rows.push({ t: T.phase === 'focus' ? '专注中' : '休息中', x: `和 ${X.esc(X.name(T.c))} 一起${T.task ? ' · ' + X.esc(T.task) : ''}`, go: 'gyxStudyOpen()' }); if (L.length) rows.push({ t: L.reduce((a, l) => a + l.min, 0) + ' 分钟', x: `今天一起自习了 ${L.reduce((a, l) => a + l.rounds, 0)} 轮`, go: 'gyxStudyOpen()' }); return { title: '📚 自习', rows }; }, 'gyxStudy');\nX.mini({ id: 'gyxStudy', icon: '📚', title: '一起自习室', desc: '番茄钟，TA 在对面也在忙；休息时催你喝水，偷偷切走会被念', onOpen: () => window.gyxStudyOpen() });\nX.ctx(id => T && String(T.c.id) === String(id) ? `【一起自习】你们正在一起自习（${T.phase === 'focus' ? '专注中，她要做的是：' + (T.task || '没说') + '，你在' + T.doing : '休息时间'}）。聊天时别拖着她聊太久，专注时间里可以催她回去学习。` : '', 'gyxStudy');\n(async () => { D = Object.assign(D, await S.get('d', {})); D.log = D.log || []; setInterval(tick, 1000); })();\nX.widget('gyxStudyW', { n: '一起自习', sizes: ['s', 'm'], tap: () => window.gyxStudyOpen(), r: w => { const m = D.log.filter(l => X.day(new Date(l.at)) === X.day()).reduce((a, l) => a + (l.min || 0), 0); return X.gw(w, '📚', '一起自习', [T ? (T.phase === 'focus' ? '专注中' : '休息中') : (m ? '今天 ' + m + ' 分钟' : '一起学一会儿'), T && T.task ? X.esc(T.task) : (m ? '一共 ' + D.log.length + ' 次自习' : '')]); } }, 'gyxStudy');\nX.memArr({ k: 'gyxStudy', ico: '📚', n: '一起自习过', d: '每次一起自习学了什么、多久', arr: () => D.log, text: x => x.task || '（没写在学什么）', field: 'task', meta: x => new Date(x.at).toLocaleString() + ' · ' + x.min + ' 分钟', save: () => S.set('d', D) }, 'gyxStudy');\n\n//# sourceURL=gyx-plugin/一起自习室.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 📚 一起自习室 出错：', e); }
/* ==== 🏃 TA是你的私教 ==== */
try { new Function('X', 'applyMacros', "/* 🏃 TA 是你的私教：拉伸、睡前瑜伽、十分钟燃脂、久坐放松……选一套，TA 在旁边数节拍、念动作、给你喝彩（也会小小吐槽你偷懒），一个动作一个倒计时。练完记一笔，连续打卡 TA 都看在眼里。身体不舒服就停，TA 不会怪你 */\nif (window.__gyxCoach) return; window.__gyxCoach = 1;\nX.feat('gyxCoach', { n: '🏃 TA 是你的私教', desc: '拉伸 / 瑜伽 / 燃脂，TA 数节拍念动作给你喝彩，记打卡' });\nconst S = X.store('coach');\nlet D = { log: [], cfg: { voice: true, style: '温柔' } };   // [{id, cid, plan, sec, done, at, say}]\nconst PLANS = {\n    '早起唤醒': { ico: '🌤️', steps: [['原地踏步', 40, '慢慢抬膝，把身体叫醒'], ['手臂画圈', 30, '向前十圈，再向后十圈'], ['左右侧弯', 30, '手举过头，往一边慢慢弯'], ['开合跳', 30, '跳不动就改成开合步，没关系'], ['深呼吸', 30, '吸四秒，呼六秒']] },\n    '久坐放松': { ico: '💺', steps: [['颈部拉伸', 30, '头慢慢往一边歪，别用力压'], ['耸肩放下', 30, '耸到耳朵，再一下子放松'], ['扩胸', 30, '双手在背后交叉，挺胸'], ['坐姿扭转', 40, '转向一边，手扶椅背'], ['手腕绕环', 20, '打字累了吧，转一转'], ['站起来伸懒腰', 20, '踮脚，往上够']] },\n    '睡前瑜伽': { ico: '🌙', steps: [['婴儿式', 60, '跪坐，身体趴下，手往前伸'], ['猫牛式', 60, '吸气抬头塌腰，呼气拱背低头'], ['仰卧扭转', 60, '躺着，膝盖倒向一边'], ['靠墙抬腿', 90, '腿搭在墙上，放松'], ['摊尸式', 90, '什么都不用做，听我说话就好']] },\n    '十分钟燃脂': { ico: '🔥', steps: [['开合跳', 40, '热起来'], ['休息', 15, '喘口气'], ['深蹲', 40, '膝盖别超过脚尖'], ['休息', 15, '喝口水'], ['高抬腿', 30, '能抬多高抬多高'], ['休息', 15, '快一半了'], ['平板支撑', 30, '屁股别撅起来'], ['休息', 15, '最后一组'], ['登山跑', 30, '冲！'], ['拉伸', 60, '慢慢放松下来']] },\n    '眼睛休息': { ico: '👀', steps: [['闭眼', 30, '什么都不看'], ['看远处', 30, '找窗外最远的地方'], ['转眼球', 30, '上下左右，慢一点'], ['掌心捂眼', 30, '搓热手心，盖在眼睛上']] }\n};\nconst CHEER = { 温柔: ['做得很好。', '慢慢来，我陪着你。', '累了就少做一点，没关系。', '你今天也很棒。', '呼吸别憋着。'], 严格: ['不许偷懒！', '还有一半，坚持住！', '我看着呢，再来。', '腰挺直！', '最后十秒，别停！'] };\nlet RUN = null;\nfunction say(c, t) { const b = document.getElementById('gyxCoSay'); if (b) b.textContent = t; if (D.cfg.voice) X.speak(c, t); }\nasync function lines(c, plan) {\n    if (X.bailu()) return null;\n    const j = X.json(await X.ask(`${X.who(c)}\\n她要做「${plan}」，你当私教陪她（${D.cfg.style}一点）。给每个动作开始时说一句话（短、口语、可以夹一点点私心），再给一句开场、一句结束。\\n动作：${PLANS[plan].steps.map(s => s[0]).join('、')}\\n只输出 JSON：{\"start\":\"\",\"steps\":[\"第1个动作说的话\"],\"end\":\"\"}`));\n    return j && Array.isArray(j.steps) ? j : null;\n}\nfunction tickRun() {\n    if (!RUN) return; const c = X.char(RUN.cid), P = PLANS[RUN.plan], st = P.steps[RUN.i];\n    if (RUN.paused) return;\n    RUN.left--; RUN.total++;\n    const b = document.getElementById('gyxCoT'); if (b) b.textContent = RUN.left;\n    const ring = document.getElementById('gyxCoRing'); if (ring) ring.style.setProperty('--p', Math.round((1 - RUN.left / st[1]) * 100));\n    if (RUN.left === Math.floor(st[1] / 2) && st[0] !== '休息' && st[1] >= 30) say(c, X.pick(X.cards(['加油', '情话'], c, 1).concat(CHEER[D.cfg.style] || CHEER['温柔'])));\n    if (RUN.left <= 3 && RUN.left > 0) try { navigator.vibrate && navigator.vibrate(40); } catch (e) {}\n    if (RUN.left <= 0) { RUN.i++; if (RUN.i >= P.steps.length) return finish(true); start(); }\n}\nfunction start() { const c = X.char(RUN.cid), st = PLANS[RUN.plan].steps[RUN.i]; RUN.left = st[1]; paint(); say(c, (RUN.L && RUN.L.steps && RUN.L.steps[RUN.i]) ? X.plain(RUN.L.steps[RUN.i]) : `${st[0]}，${st[1]} 秒。${st[2]}。`); }\nasync function finish(done) {\n    if (!RUN) return; clearInterval(RUN.t); const r = RUN, c = X.char(r.cid); RUN = null; X.stopSpeak();\n    const end = done ? ((r.L && r.L.end) || X.pick(['练完啦！今天的你闪闪发光。', '好，收工。去喝水，然后抱一下。', '做完了？我就知道你可以。'])) : X.pick(['今天就到这儿吧，能动一动已经很好了。', '没关系，下次我们再继续。']);\n    const it = { id: 'co' + Date.now().toString(36), cid: r.cid, plan: r.plan, sec: r.total, done: !!done, at: Date.now(), say: X.plain(end), steps: r.i }; D.log.unshift(it); await S.set('d', D);\n    if (D.cfg.voice) X.speak(c, it.say); window.gyxCoachOpen(r.cid, it.id);\n}\nfunction paint() {\n    const b = document.getElementById('gyxCoRun'); if (!b || !RUN) return; const P = PLANS[RUN.plan], st = P.steps[RUN.i];\n    b.innerHTML = `<div class=\"co-step\">${RUN.i + 1} / ${P.steps.length}</div><div id=\"gyxCoRing\" class=\"co-ring\" style=\"--p:0\"><b id=\"gyxCoT\">${RUN.left}</b></div><div class=\"co-name\">${X.esc(st[0])}</div><div class=\"gyx-tip\" style=\"text-align:center\">${X.esc(st[2])}</div><div id=\"gyxCoSay\" class=\"co-say\"></div>\n        <div class=\"co-next\">${P.steps.slice(RUN.i + 1, RUN.i + 3).map(s => `下一个：${X.esc(s[0])} ${s[1]}″`).join(' · ')}</div>\n        <div class=\"gyx-row\" style=\"justify-content:center\"><button class=\"gyx-btn lite\" onclick=\"gyxCoachPause()\">${RUN.paused ? '▶ 继续' : '⏸ 暂停'}</button><button class=\"gyx-btn lite\" onclick=\"gyxCoachSkip()\">跳过 ›</button><button class=\"gyx-btn lite\" onclick=\"gyxCoachStop()\">不练了</button></div>`;\n}\nwindow.gyxCoachGo = async (cid, plan, fast) => {\n    const c = X.char(cid) || X.cur(); if (!c || !PLANS[plan]) return; if (RUN) clearInterval(RUN.t);\n    RUN = { cid: String(c.id), plan, i: 0, left: 0, total: 0, L: null };\n    X.panel('gyxCoOv', PLANS[plan].ico + ' ' + plan, `<div id=\"gyxCoRun\" class=\"co-run\"><div class=\"gyx-tip\" style=\"text-align:center\">${X.esc(X.name(c))} ${X.v('在换衣服……', '准备好了，在等你', '把垫子铺好了')}</div></div><div class=\"gyx-tip\" style=\"text-align:center\">⚠️ 哪里疼、头晕就停下来，TA 不会怪你</div>`);\n    const ov = document.getElementById('gyxCoOv'), rm = ov.remove.bind(ov); ov.remove = () => { if (RUN) { clearInterval(RUN.t); RUN = null; X.stopSpeak(); } rm(); };\n    RUN.L = await lines(c, plan); if (!RUN) return;\n    say(c, X.plain((RUN.L && RUN.L.start) || X.pick(['好，开始了。跟着我。', '准备——开始！', '今天我陪你练。'])));\n    start(); RUN.t = setInterval(tickRun, fast ? 5 : 1000);\n};\nwindow.gyxCoachPause = () => { if (RUN) { RUN.paused = !RUN.paused; paint(); } };\nwindow.gyxCoachSkip = () => { if (!RUN) return; RUN.left = 1; tickRun(); };\nwindow.gyxCoachStop = () => finish(false);\nwindow.gyxCoachCfg = (k, v) => { D.cfg[k] = v; S.set('d', D); };\nwindow.gyxCoachData = () => D;\nconst streak = cid => { const ds = new Set(D.log.filter(x => x.cid === cid && x.done).map(x => X.day(new Date(x.at)))); const d = new Date(); if (!ds.has(X.day(d))) d.setDate(d.getDate() - 1); let n = 0; while (ds.has(X.day(d))) { n++; d.setDate(d.getDate() - 1); } return n; };\nwindow.gyxCoachOpen = function (who, hl) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), L = D.log.filter(x => x.cid === cid), last = hl && L.find(x => x.id === hl);\n    X.panel('gyxCoOv', '🏃 TA 是你的私教', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxCoachOpen')}<span class=\"gyx-tip\">连续 ${streak(cid)} 天 · 一共 ${L.filter(x => x.done).length} 次</span></div>\n        ${last ? `<div class=\"gyx-card\"><b>${last.done ? '✅ 练完了' : '⏹ 先到这儿'}</b> · ${X.esc(last.plan)} · ${Math.round(last.sec / 60)} 分钟<div>${X.esc(X.name(c))}：${X.esc(last.say)}</div></div>` : ''}\n        <div class=\"co-plans\">${Object.keys(PLANS).map(k => `<div onclick=\"gyxCoachGo('${cid}','${k}')\"><span>${PLANS[k].ico}</span><b>${k}</b><em>${Math.round(PLANS[k].steps.reduce((a, s) => a + s[1], 0) / 60)} 分钟 · ${PLANS[k].steps.length} 个动作</em></div>`).join('')}</div>\n        <div class=\"gyx-row gyx-tip\">TA 的风格 ${['温柔', '严格'].map(s => `<span class=\"gyx-chip${D.cfg.style === s ? ' on' : ''}\" onclick=\"gyxCoachCfg('style','${s}');gyxCoachOpen('${cid}')\">${s}</span>`).join('')} <label><input type=\"checkbox\" ${D.cfg.voice ? 'checked' : ''} onchange=\"gyxCoachCfg('voice',this.checked)\"> TA 念出来</label></div>\n        <div style=\"font-weight:700;margin:12px 0 4px\">打卡记录</div>${L.slice(0, 20).map(x => `<div class=\"gyx-tip\">${new Date(x.at).toLocaleString()} · ${x.done ? '✅' : '⏹'} ${X.esc(x.plan)} · ${Math.round(x.sec / 60)} 分钟</div>`).join('') || '<div class=\"gyx-tip\">还没练过</div>'}`);\n};\nX.ctx(id => { const L = D.log.filter(x => x.cid === String(id)); if (!L.length) return ''; const x = L[0]; return `【你是她的私教】连续打卡 ${streak(String(id))} 天。${Date.now() - x.at < 864e5 ? `今天她刚做了「${x.plan}」${x.done ? '' : '（没做完）'}。` : ''}`; }, 'gyxCoach');\nX.action({ key: 'gyx_coach', label: '叫她起来活动一下，你陪着', hint: 'TA 是你的私教', need: c => !D.log.some(x => x.cid === String(c.id) && Date.now() - x.at < 864e5),\n    run: async c => { const h = new Date().getHours(), p = h < 10 ? '早起唤醒' : h >= 21 ? '睡前瑜伽' : X.pick(['久坐放松', '眼睛休息', '十分钟燃脂']); X.notify(c, `🏃 ${X.esc(X.name(c))}：${X.v('起来动一动？', '我陪你练一会儿', '该活动啦')}`, p, () => window.gyxCoachGo(c.id, p)); return (await X.reach(c, `你想叫她起来做一组「${p}」，你在旁边陪她（「🏃 TA 是你的私教」里）。用你的风格叫她`)) ? '叫你起来活动' : null; } }, 'gyxCoach');\nX.today(() => { const L = D.log.filter(x => X.day(new Date(x.at)) === X.day()); return { title: '🏃 私教打卡', rows: L.length ? L.map(x => ({ t: x.done ? '✅' : '⏹', x: X.esc(x.plan) + ' · ' + Math.round(x.sec / 60) + ' 分钟', go: `gyxCoachOpen('${x.cid}')` })) : [{ t: '还没练', x: '动一动？', go: 'gyxCoachOpen()' }] }; }, 'gyxCoach');\nX.widget('gyxCoachW', { n: '私教打卡', sizes: ['s', 'm'], tap: () => window.gyxCoachOpen(), r: w => { const c = X.cur(), n = c ? streak(String(c.id)) : 0; return X.gw(w, '🏃', '私教打卡', [n ? '连续 ' + n + ' 天' : '今天还没练', D.log[0] ? X.esc(D.log[0].plan) : '']); } }, 'gyxCoach');\nX.memArr({ k: 'gyxCoach', ico: '🏃', n: '私教打卡', d: '练过的和 TA 说的话', arr: () => D.log, field: 'say', text: x => x.plan + '：' + x.say, edit: (x, v) => { x.say = v.replace(/^[^：]*：/, ''); }, meta: x => new Date(x.at).toLocaleString() + (x.done ? ' · 完成' : ' · 中途停'), save: () => S.set('d', D) }, 'gyxCoach');\nX.css('gyxCoCss', `.co-plans{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0}.co-plans div{border-radius:16px;background:#f5f7fa;padding:12px;cursor:pointer}.co-plans span{font-size:28px}.co-plans b{display:block}.co-plans em{font-style:normal;font-size:11.5px;color:#999}.co-run{text-align:center;padding:6px 0}.co-step{font-size:12px;color:#999}.co-ring{width:150px;height:150px;margin:8px auto;border-radius:50%;background:conic-gradient(#34c759 calc(var(--p)*1%),#e9f5ec 0);display:flex;align-items:center;justify-content:center;position:relative}.co-ring:before{content:'';position:absolute;inset:10px;border-radius:50%;background:#fff}.co-ring b{position:relative;font-size:52px;font-weight:800;font-variant-numeric:tabular-nums}.co-name{font-size:22px;font-weight:800}.co-say{min-height:46px;margin:10px auto;max-width:360px;padding:9px 14px;border-radius:16px;background:#f0fbf3;color:#26733d;font-size:14.5px}.co-next{font-size:12px;color:#aaa}`);\nX.mini({ id: 'gyxCoach', icon: '🏃', title: 'TA 是你的私教', desc: '拉伸 / 瑜伽 / 燃脂，TA 陪你练', cat: '生活', onOpen: () => window.gyxCoachOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.log = D.log || []; D.cfg = Object.assign({ voice: true, style: '温柔' }, D.cfg || {}); })();\n\n//# sourceURL=gyx-plugin/TA是你的私教.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🏃 TA是你的私教 出错：', e); }
/* ==== ✈️ 一起旅行 ==== */
try { new Function('X', 'applyMacros', "/* ✈️ 一起旅行：和 TA 一起计划一趟好几天的旅行——定目的地和日子，TA 帮你排每天的行程、列要带的东西；出发那几天 TA 每天陪你走，到了地方会说话；回来还有一份旅行手账（原来的「约出去」只能去一个地点，这个是整趟旅行） */\nif (window.__gyxTrip) return; window.__gyxTrip = 1;\nX.feat('gyxTrip', { n: '✈️ 一起旅行', desc: '计划好几天的旅行，TA 排行程、出发后每天陪你' });\nconst S = X.store('trip');\nlet D = { trips: [] };   // {id, cid, to, start, days, plan:[{d, title, items:[{t, what}]}], pack:[{t, ok}], notes:[{d, by, t, at}], said:{}, at}\nconst dk = d => X.day(d);\nconst pd = s => { const [y, m, d] = String(s).split('-').map(Number); return new Date(y, m - 1, d); };\nconst dayIdx = (t, now) => { const n = new Date(now || Date.now()); n.setHours(0, 0, 0, 0); return Math.round((n - pd(t.start)) / 86400000); };   // 0 = 第一天\nconst state = t => { const i = dayIdx(t); return i < 0 ? 'before' : i < t.days ? 'on' : 'after'; };\nasync function plan(c, t) {\n    if (X.bailu()) {\n        const A = ['睡到自然醒，找家早餐店', '去当地最有名的地方走走', '逛一条老街', '吃当地的小吃', '找个地方看日落', '晚上散步回酒店', '去一家咖啡馆坐坐', '逛菜市场', '去博物馆', '买点小纪念品'];\n        t.plan = Array.from({ length: t.days }, (_, i) => ({ d: i + 1, title: i === 0 ? '出发 & 到达' : i === t.days - 1 ? '最后一天 & 回家' : '第 ' + (i + 1) + ' 天', items: [['09:00', X.pick(A)], ['13:00', X.pick(A)], ['18:00', X.pick(A)]].map(([a, b]) => ({ t: a, what: b })) }));\n        t.pack = ['身份证', '充电器', '换洗衣服', '牙刷', '雨伞', '常用药'].map(x => ({ t: x, ok: false }));\n        t.hi = X.cards(['旅行', '聊天'], c, 1)[0] || '好期待和你一起去。';\n        return t;\n    }\n    const j = X.json(await X.ask(`${X.who(c)}\\n你们要一起去「${t.to}」旅行 ${t.days} 天，${t.start} 出发。${t.want ? '她想：' + t.want + '。' : ''}\\n最近聊天：\\n${X.recent(c, 8)}\\n\\n按你的性格帮你们排行程（每天 3~5 项，具体到地方/吃什么，别太赶），再列一张要带的东西清单（按目的地和季节），最后用你的口吻说一句对这趟旅行的期待。\\n只输出 JSON：{\"plan\":[{\"d\":1,\"title\":\"这天的主题\",\"items\":[{\"t\":\"09:00\",\"what\":\"做什么\"}]}],\"pack\":[\"要带的\"],\"hi\":\"一句话\"}`));\n    t.plan = (j && Array.isArray(j.plan) ? j.plan : []).slice(0, t.days).map((p, i) => ({ d: i + 1, title: String(p.title || '第 ' + (i + 1) + ' 天'), items: (p.items || []).map(x => ({ t: String(x.t || ''), what: String(x.what || '') })) }));\n    while (t.plan.length < t.days) t.plan.push({ d: t.plan.length + 1, title: '自由活动', items: [] });\n    t.pack = (j && j.pack || ['身份证', '充电器', '换洗衣服']).map(x => ({ t: String(x), ok: false }));\n    t.hi = (j && j.hi) || '好期待和你一起去。';\n    return t;\n}\nwindow.gyxTripNew = async function (o) {\n    o = o || {}; const g = id => ((document.getElementById(id) || {}).value || '').trim();\n    const to = o.to || g('gyxTpTo'), start = o.start || g('gyxTpSt'), days = +(o.days || g('gyxTpDy') || 3), want = o.want != null ? o.want : g('gyxTpWt');\n    const c = X.char(o.cid || window.GYX_TRIP_WHO) || X.cur(); if (!c) return null;\n    if (!to || !start) { X.toast(X.v('目的地和出发日子都要填', '还差一点', '去哪儿？哪天走？')); return null; }\n    const btn = document.getElementById('gyxTpGo'); if (btn) { btn.disabled = true; btn.textContent = X.v('TA 在排行程……', 'TA 在翻攻略……'); }\n    const t = await plan(c, { id: 'tp' + Date.now(), cid: String(c.id), to, start, days: Math.max(1, days), want, notes: [], said: {}, at: Date.now() });\n    D.trips.unshift(t); await S.set('d', D);\n    X.say(c, `✈️ ${t.hi}`);\n    window.gyxTripOpen(t.id); return t;\n};\nwindow.gyxTripPack = async (id, i) => { const t = D.trips.find(x => x.id === id); if (!t) return; t.pack[i].ok = !t.pack[i].ok; await S.set('d', D); };\nwindow.gyxTripNote = async id => { const t = D.trips.find(x => x.id === id), v = ((document.getElementById('gyxTpN') || {}).value || '').trim(); if (!t || !v) return; const d = Math.min(t.days, Math.max(1, dayIdx(t) + 1)); t.notes.push({ d, by: 'me', t: v, at: Date.now() }); await S.set('d', D); const c = X.char(t.cid); if (c) X.reach(c, `你们正在「${t.to}」旅行（第 ${d} 天），她在旅行手账里写了：「${v}」，回应她`); window.gyxTripOpen(id); };\nwindow.gyxTripDel = async id => { D.trips = D.trips.filter(x => x.id !== id); await S.set('d', D); window.gyxTripOpen(); };\nwindow.GYX_TRIP_WHO = '';\nwindow.gyxTripWho = v => { window.GYX_TRIP_WHO = v; };\nwindow.gyxTripOpen = function (id) {\n    const t = id && D.trips.find(x => x.id === id);\n    if (!t) {\n        window.GYX_TRIP_WHO = String((X.cur() || {}).id || '');\n        const tm = new Date(Date.now() + 7 * 86400000);\n        X.panel('gyxTpOv', '✈️ 一起旅行', `${D.trips.map(x => `<div class=\"tp-it\" onclick=\"gyxTripOpen('${x.id}')\"><b>${X.esc(x.to)}</b><span>${x.start} · ${x.days} 天 · 和 ${X.esc(X.name(X.char(x.cid)))}</span><em>${{ before: (-dayIdx(x)) + ' 天后出发', on: '旅行中 · 第 ' + (dayIdx(x) + 1) + ' 天', after: '回来了' }[state(x)]}</em></div>`).join('') || '<div class=\"gyx-tip\">还没有旅行。想和 TA 去哪儿？</div>'}\n            <div class=\"gyx-card\"><div class=\"gyx-tip\">计划一趟新旅行</div><div class=\"gyx-row\"><input id=\"gyxTpTo\" class=\"gyx-who\" placeholder=\"去哪儿（比如：大理）\" style=\"flex:2\"><input id=\"gyxTpDy\" class=\"gyx-who\" type=\"number\" min=\"1\" value=\"3\" style=\"width:64px\"> 天</div>\n            <div class=\"gyx-row\">出发：<input id=\"gyxTpSt\" class=\"gyx-who\" type=\"date\" value=\"${dk(tm)}\"> 和谁：${X.whoSel(window.GYX_TRIP_WHO, 'gyxTripWho')}</div><input id=\"gyxTpWt\" class=\"gyx-in\" placeholder=\"想怎么玩（可空）：比如想看海、想吃好吃的、别太累\"><div class=\"gyx-row\"><button id=\"gyxTpGo\" class=\"gyx-btn\" onclick=\"gyxTripNew()\">让 TA 排行程</button></div></div>`);\n        return;\n    }\n    const st = state(t), cur = dayIdx(t);\n    X.panel('gyxTpOv', '✈️ ' + X.esc(t.to), `<div class=\"tp-hd\"><b>${X.esc(t.to)}</b><span>${t.start} 出发 · ${t.days} 天 · 和 ${X.esc(X.name(X.char(t.cid)))}</span><em>${{ before: '还有 ' + (-cur) + ' 天出发', on: '旅行中 · 第 ' + (cur + 1) + ' 天', after: '旅行结束啦' }[st]}</em></div>\n        ${t.plan.map((p, i) => `<div class=\"tp-day${st === 'on' && i === cur ? ' now' : ''}\"><div class=\"tp-dn\">Day ${p.d}<small>${dk(new Date(pd(t.start).getTime() + i * 86400000)).slice(5)}</small></div><div><b>${X.esc(p.title)}</b>${p.items.map(x => `<p><i>${X.esc(x.t)}</i>${X.esc(x.what)}</p>`).join('')}${t.notes.filter(n => n.d === p.d).map(n => `<p class=\"tp-n\">${n.by === 'me' ? '我' : X.esc(X.name(X.char(n.by)))}：${X.esc(n.t)}</p>`).join('')}</div></div>`).join('')}\n        <div class=\"gyx-card\"><div class=\"gyx-tip\">要带的东西</div>${t.pack.map((x, i) => `<label class=\"tp-pk\"><input type=\"checkbox\" ${x.ok ? 'checked' : ''} onchange=\"gyxTripPack('${t.id}',${i})\"> ${X.esc(x.t)}</label>`).join('')}</div>\n        ${st !== 'before' ? `<div class=\"gyx-row\"><input id=\"gyxTpN\" class=\"gyx-in\" style=\"flex:1\" placeholder=\"在旅行手账里写一句\"><button class=\"gyx-btn\" onclick=\"gyxTripNote('${t.id}')\">写下</button></div>` : ''}\n        <div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"gyxTripOpen()\">← 所有旅行</button><button class=\"gyx-btn lite\" onclick=\"gyxTripDel('${t.id}')\">删掉这趟</button></div>`);\n};\nwindow.gyxTripData = () => D;\n// 旅行前三天、出发那几天每天，TA 会来说话\nasync function daily(c, t) {\n    const st = state(t), i = dayIdx(t), k = st + ':' + X.day();\n    if (t.said[k]) return null; t.said[k] = 1; await S.set('d', D);\n    if (st === 'before' && -i <= 3) return X.reach(c, `再过 ${-i} 天你们就要去「${t.to}」旅行了，提醒她收拾东西（清单里还有 ${t.pack.filter(x => !x.ok).length} 样没勾）、说说你的期待`);\n    if (st === 'on') { const p = t.plan[i] || {}, txt = `你们正在「${t.to}」旅行，今天是第 ${i + 1} 天「${p.title || ''}」，安排是：${(p.items || []).map(x => x.t + ' ' + x.what).join('；')}。像真的和她在一起旅行那样跟她说话（今天去哪、看到什么、你的感受）`; const r = await X.reach(c, txt); if (r) t.notes.push({ d: i + 1, by: String(c.id), t: X.v('今天也很开心', '想把今天记下来', '和你一起真好'), at: Date.now() }); await S.set('d', D); return r; }\n    if (st === 'after' && i === t.days) return X.reach(c, `你们刚从「${t.to}」旅行回来，回味一下这趟旅行最难忘的瞬间`);\n    return null;\n}\nasync function tick() { if (!X.on('gyxTrip')) return; const h = new Date().getHours(); if (h < 8 || h > 22) return; for (const t of D.trips) { const c = X.char(t.cid); if (!c || X.auto(c)) continue; await daily(c, t); } }\nX.action({ key: 'gyx_trip', label: '聊聊你们计划的旅行 / 旅行中陪她 / 提议一起去旅行', hint: '想和她出去走走', need: () => true,\n    run: async c => { const t = D.trips.find(x => x.cid === String(c.id) && state(x) !== 'after'); if (t) return (await daily(c, t)) ? '聊了聊你们的旅行' : null; return (await X.reach(c, '你突然很想和她一起去旅行，说说你想去哪、为什么（她可以在「一起旅行」里定下来）')) ? '想和你去旅行' : null; } }, 'gyxTrip');\nX.ctx(id => { const t = D.trips.find(x => x.cid === String(id) && state(x) !== 'after') || D.trips.find(x => x.cid === String(id)); if (!t) return ''; const st = state(t), i = dayIdx(t); return `【你们的旅行】去「${t.to}」${t.days} 天，${t.start} 出发。` + (st === 'before' ? `还有 ${-i} 天出发。` : st === 'on' ? `现在正在旅行，第 ${i + 1} 天：${(t.plan[i] || {}).title || ''}。` : '已经回来了。'); }, 'gyxTrip');\nX.today(() => ({ title: '✈️ 旅行', rows: D.trips.filter(t => state(t) !== 'after').map(t => { const st = state(t), i = dayIdx(t); return { t: st === 'on' ? 'Day ' + (i + 1) : (-i) + ' 天后', x: st === 'on' ? `${X.esc(t.to)}：${X.esc((t.plan[i] || {}).title || '')}` : `和 ${X.esc(X.name(X.char(t.cid)))} 去${X.esc(t.to)}`, go: `gyxTripOpen('${t.id}')` }; }) }), 'gyxTrip');\nX.widget('gyxTripW', { n: '一起旅行', sizes: ['s', 'm'], tap: () => { const t = D.trips.find(x => state(x) !== 'after'); window.gyxTripOpen(t && t.id); }, r: w => { const t = D.trips.find(x => state(x) !== 'after'); if (!t) return X.gw(w, '✈️', '一起旅行', ['想去哪儿？']); const st = state(t), i = dayIdx(t); return X.gw(w, '✈️', '一起旅行', [st === 'on' ? '第 ' + (i + 1) + ' 天' : (-i) + ' 天后出发', X.esc(t.to), st === 'on' ? X.esc((t.plan[i] || {}).title || '') : '']); } }, 'gyxTrip');\nX.css('gyxTpCss', `.tp-it{padding:12px 14px;border-radius:16px;background:#f0f7ff;margin:8px 0;cursor:pointer}.tp-it b{font-size:17px}.tp-it span{display:block;font-size:12.5px;color:#888}.tp-it em{font-style:normal;font-size:12.5px;color:#3a86ff}\n.tp-hd{padding:16px;border-radius:20px;background:linear-gradient(135deg,#a0c4ff,#caffbf);margin-bottom:8px}.tp-hd b{font-size:24px;display:block}.tp-hd span{font-size:13px;color:#335}.tp-hd em{display:block;font-style:normal;margin-top:4px;font-weight:600;color:#1d3557}\n.tp-day{display:flex;gap:12px;padding:10px 4px;border-bottom:1px dashed #e6e6ea}.tp-day.now{background:#fffbe6;border-radius:12px}.tp-dn{width:54px;flex-shrink:0;font-weight:700;color:#3a86ff;font-size:14px}.tp-dn small{display:block;font-weight:normal;color:#aaa;font-size:11px}.tp-day b{font-size:15px}.tp-day p{margin:4px 0;font-size:13.5px}.tp-day p i{font-style:normal;color:#999;margin-right:8px;font-size:12px}.tp-day p.tp-n{color:#8e4ec6}\n.tp-pk{display:inline-block;margin:4px 10px 4px 0;font-size:13.5px}`);\nX.mini({ id: 'gyxTrip', icon: '✈️', title: '一起旅行', desc: '计划好几天的旅行：TA 排行程、列清单，出发后每天陪你', onOpen: () => window.gyxTripOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.trips = D.trips || []; setTimeout(tick, 40000); setInterval(tick, 30 * 60000); })();\nX.memArr({ k: 'gyxTrip', ico: '✈️', n: '一起去的旅行', d: '目的地（行程在旅行里看）', arr: () => D.trips, text: x => x.to, field: 'to', meta: x => x.start + ' · ' + x.days + ' 天 · 手账 ' + (x.notes || []).length + ' 条', save: () => S.set('d', D) }, 'gyxTrip');\n\n//# sourceURL=gyx-plugin/一起旅行.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] ✈️ 一起旅行 出错：', e); }
